<style>
/* Shared My TV workspace design, independent of reseller-panel theme overrides. */
:root{color-scheme:dark;--bg:#0b1017;--text:#f3f6fa;--text-muted:#9aaabd;--muted:#9aaabd;--card:#151d28;--border:#293544;--muted-bg:#101721;--accent:#d5f58a;--warning:#ffd69a;font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;background:var(--bg);color:var(--text)}
*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at 90% 0%,#1b2b302e,transparent 55%),var(--bg);color:var(--text);font-size:14px;line-height:1.55}a{color:var(--accent);text-underline-offset:3px}button,input,select,textarea{font:inherit}button,a,input,select,textarea,summary{-webkit-tap-highlight-color:transparent}button{cursor:pointer}p{line-height:1.65}h1,h2,h3{color:var(--text);line-height:1.25;letter-spacing:-.025em}h3{font-size:1rem}code{font-family:ui-monospace,SFMono-Regular,monospace;font-size:.85em;overflow-wrap:anywhere}button:disabled,fieldset:disabled{opacity:.55}button:disabled{cursor:not-allowed}
:focus-visible{outline:2px solid var(--accent);outline-offset:4px}input:focus-visible,select:focus-visible,textarea:focus-visible{outline-offset:2px}
.am-page{max-width:1440px;margin:auto;padding:0 32px 64px;color:var(--text)}.am-page h1{font-size:clamp(1.6rem,3vw,2rem);margin:8px 0 12px}.am-page h2{font-size:1.15rem;margin:0 0 12px}.am-page .am-muted{font-size:.85rem;color:var(--text-muted);line-height:1.6}
.am-top{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:24px 0;margin:0 0 32px;border:0;border-bottom:1px solid var(--border);border-radius:0;background:none}
.am-brand{display:flex;align-items:center;gap:12px;text-decoration:none;color:var(--text)}.am-logo{display:grid;place-items:center;flex-shrink:0;width:44px;height:44px;background:var(--accent);color:var(--bg);border-radius:13px;font-size:1.2rem;font-weight:800;letter-spacing:-1px}.am-brand strong{display:block;font-size:1.1rem;letter-spacing:-.03em}.am-brand small{display:block;color:var(--text-muted);font-size:.72rem}.am-account{text-align:right;display:grid;gap:3px;font-size:.8rem}.am-account>span{max-width:320px;overflow-wrap:anywhere}.am-account a{color:var(--text-muted);font-size:.75rem;text-decoration:none}
.am-workspace{display:grid;grid-template-columns:210px minmax(0,1fr);gap:36px}.am-sidebar{align-self:start;position:sticky;top:24px}.am-content{min-width:0}.am-nav{display:block;margin:0}.am-nav-group{display:grid;gap:5px;margin-bottom:26px}.am-nav-label,.am-eyebrow{font-size:.65rem;letter-spacing:.13em;text-transform:uppercase;font-weight:700;color:var(--text-muted)}.am-nav-label{padding:0 14px;margin-bottom:6px}.am-nav a{display:flex;align-items:center;justify-content:space-between;gap:6px;background:none;border:0;border-radius:10px;padding:12px 14px;font-size:.82rem;color:var(--text-muted);font-weight:500;text-decoration:none;text-align:left}.am-nav a>span{opacity:0}.am-nav a:hover{background:var(--card);color:var(--text)}.am-nav a[aria-current=page]{background:#d5f58a12;color:var(--accent);box-shadow:inset 3px 0 var(--accent);font-weight:650}.am-nav a[aria-current=page]>span{opacity:1}.am-sidebar-license{display:flex;gap:8px;align-items:center;margin:10px 14px;font-size:.75rem;color:var(--text-muted);text-decoration:none}.am-sidebar-license>span:last-child{margin-left:auto}.am-dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:var(--accent);flex-shrink:0}
.am-section-title{margin:0 0 26px}.am-section-title p{margin:0}.am-page .card,.am-admin-page .am-box{background:var(--card);border:1px solid var(--border);border-radius:18px;padding:26px;box-shadow:none}.am-page .am-grid{gap:20px}.am-page [data-am-section]{scroll-margin-top:24px}.am-page [data-am-section]:not([hidden])~[data-am-section]:not([hidden]){margin-top:28px}.am-page [hidden]{display:none!important}
.btn,.am-page .btn,.am-admin-page .btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;min-height:44px;padding:11px 17px;border:1px solid #384657;border-radius:10px;color:var(--text);background:transparent;text-decoration:none;font-size:.82rem;font-weight:600;line-height:1.4;white-space:normal;text-align:center;box-shadow:none}.btn:hover{background:#ffffff08}.btn.btn-primary,.am-page .btn-primary,.am-admin-page .btn-primary{background:var(--accent);border-color:var(--accent);color:var(--bg)}.btn-primary:hover{filter:brightness(1.06)}
.am-page input:not([type=checkbox]):not([type=hidden]),.am-page select,.am-page textarea,.am-admin-page input:not([type=checkbox]):not([type=hidden]),.am-admin-page select{display:block;width:100%;min-width:0;max-width:100%;min-height:46px;margin:0;padding:11px 13px;border:1px solid #384657;border-radius:10px;background:var(--bg);color:var(--text);font:inherit;box-shadow:none}.am-page input::placeholder,.am-admin-page input::placeholder{color:#77889e}.am-page label.am-field>span{font-size:.78rem;font-weight:600;letter-spacing:0;text-transform:none}.am-page .am-switch{font-size:.85rem;gap:12px;padding:10px 0}.am-page .am-switch input,.am-admin-page input[type=checkbox]{accent-color:var(--accent)}.am-page .am-switch small{font-size:.75rem}.am-page .am-actions{border-radius:14px;padding:18px 22px;background:var(--card)}
.am-notice,.flash{padding:14px 18px;margin:0 0 20px;background:#ffd69a08;border:1px solid #ffd69a30;border-radius:12px;color:var(--text);font-size:.82rem;line-height:1.6}.flash.success{border-color:#d5f58a40;background:#d5f58a0a}.flash.error,[role=alert]{color:#ffceca}.am-page .am-help{font-size:.8rem;padding:12px 0;color:var(--text-muted);margin:8px 0 18px}.am-help summary{cursor:pointer}.am-help p{max-width:75ch}.am-page .am-empty{padding:40px 24px;color:var(--text-muted);background:var(--muted-bg);border:1px dashed #384657}.am-page .am-filters{background:var(--muted-bg);padding:18px;border:1px solid var(--border);gap:14px}.am-page .am-summary{gap:8px}.am-summary span{font-size:.75rem;border-radius:8px;padding:6px 10px;background:transparent}.am-page .am-package{border-radius:12px;background:var(--muted-bg);margin-bottom:10px}.am-package summary{padding:18px;font-size:.85rem}.am-package summary:hover{background:#ffffff03}.am-package summary small{font-size:.72rem;line-height:1.55}.am-price-badge[data-status=enabled]{color:var(--accent)}.am-package[open]{background:var(--card)}.am-page .am-price{padding:22px}.am-package .btn{margin:4px 4px 4px 0}.am-page .am-pager{font-size:.8rem}.am-page .am-pager .am-muted{font-size:.75rem}
.am-metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin-bottom:22px}.am-metric{display:grid;gap:12px;padding:22px;background:var(--card);border:1px solid var(--border);border-radius:16px;text-decoration:none;color:var(--text)}.am-metric>span{font-size:.75rem;color:var(--text-muted)}.am-metric>strong{font-size:clamp(1.2rem,2vw,1.75rem);font-weight:600;letter-spacing:-.04em}.am-metric em{font-size:.7rem;font-style:normal;margin-left:8px;color:var(--text-muted);letter-spacing:0}.am-metric small{font-size:.7rem;color:var(--text-muted)}.am-metric:hover{border-color:#d5f58a60}.am-page .am-overview-grid{grid-template-columns:minmax(0,1.5fr) minmax(0,1fr);margin-bottom:22px}.am-card-heading{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:16px}.am-card-heading h2{margin:8px 0 0}.am-pill{display:inline-flex;align-items:center;gap:7px;padding:6px 11px;background:var(--muted-bg);border:1px solid var(--border);border-radius:99px;font-size:.72rem;white-space:nowrap}.am-pill-success{color:var(--accent);background:#d5f58a0a;border-color:#d5f58a30}.am-setup-item{display:flex;align-items:center;gap:12px;padding:18px 0;border-bottom:1px solid var(--border);text-decoration:none;color:var(--text)}.am-setup-item>span:nth-child(2){flex:1;min-width:0}.am-setup-item strong{font-size:.85rem;font-weight:600}.am-setup-item small{display:block;margin-top:4px;font-size:.75rem;color:var(--text-muted)}.am-step{display:grid;place-items:center;flex-shrink:0;width:28px;height:28px;border:1px solid var(--border);border-radius:50%;color:var(--text-muted)}.am-step.is-done{color:var(--accent);border-color:#d5f58a30;background:#d5f58a0a}.am-footnote{font-size:.75rem!important;margin:18px 0 0}.am-license-teaser{display:flex;align-items:flex-start;flex-direction:column;gap:18px}.am-license-teaser h2,.am-license-teaser p{margin:0}.am-license-teaser .btn{margin-top:auto}.am-promo-callout{display:flex;gap:24px;align-items:center;justify-content:space-between}.am-promo-callout h2{margin:8px 0}.am-promo-callout p{margin:0}.am-promo-callout .btn{flex-shrink:0}.am-details{margin:26px 0 0}.am-details>div{display:grid;grid-template-columns:minmax(120px,1fr) minmax(0,2fr);gap:20px;padding:18px 0;border-top:1px solid var(--border);font-size:.85rem}.am-details dt{color:var(--text-muted)}.am-details dd{margin:0;overflow-wrap:anywhere}.am-license-detail>.btn{margin-top:22px}
.am-admin-page main{max-width:1100px;padding:28px 24px 64px}.am-admin-page h1{font-size:2rem}.am-admin-page h2{font-size:1.1rem}.am-admin-page label{font-size:.8rem}.am-admin-page label input,.am-admin-page label select{margin-top:8px!important}.am-admin-page p,.am-admin-page small{color:var(--text-muted);font-size:.85rem}.am-admin-page .key{color:var(--accent);background:var(--bg);border:1px solid #d5f58a50}.am-admin-page details:not(.am-box){background:var(--muted-bg);border-color:var(--border)}.am-admin-page summary{font-size:.85rem;line-height:1.7}.am-admin-page td,.am-admin-page th{font-size:.75rem}.am-admin-page [role=alert]{color:#ffceca}.am-admin-page .reseller-picker small{display:block;margin-top:8px}
@media(max-width:1050px){.am-workspace{grid-template-columns:185px minmax(0,1fr);gap:24px}.am-page{padding-left:24px;padding-right:24px}.am-page .am-overview-grid{grid-template-columns:1fr}.am-metrics{gap:10px}.am-metric{padding:18px}.am-promo-callout{align-items:flex-start;flex-direction:column}}
@media(max-width:760px){.am-workspace{display:block}.am-sidebar{position:static}.am-nav{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin:0 0 24px}.am-nav-group{display:contents}.am-nav-label,.am-sidebar-license{display:none}.am-nav a{border:1px solid var(--border);padding:12px;background:var(--card);font-size:.8rem}.am-top{margin-bottom:20px}.am-page .am-grid{grid-template-columns:1fr}.am-metrics{grid-template-columns:1fr}.am-metric{grid-template-columns:1fr auto;gap:6px 16px}.am-metric strong{grid-column:2;grid-row:1/3;align-self:center;font-size:1.3rem}.am-page .am-filters{grid-template-columns:1fr 1fr}.am-page .am-filters .am-search{grid-column:1/-1}.am-page .card{padding:22px}.am-account>span{max-width:150px}.am-page{padding:0 16px 40px}.am-promo-callout .btn{width:100%}}
@media(max-width:420px){.am-page .card{padding:18px}.am-page .am-filters{padding:12px;gap:12px}.am-details>div{grid-template-columns:1fr;gap:5px}.am-account>span{max-width:115px}.am-brand small{font-size:.65rem}.am-top{gap:12px}.am-admin-page main{padding:22px 16px}}
.am-menu-toggle{display:none}
@media(max-width:760px){.am-enhanced .am-menu-toggle{display:flex;align-items:center;justify-content:space-between;width:100%;min-height:48px;padding:12px 16px;margin:0 0 22px;border:1px solid var(--border);border-radius:12px;background:var(--card);color:var(--text);font-size:.85rem}.am-enhanced .am-menu-toggle[aria-expanded=false]+.am-nav{display:none}}
@media(prefers-reduced-motion:no-preference){a,button{transition:background-color .15s,border-color .15s,color .15s}}
</style>
